"use client";

import { CornerDownRight } from "lucide-react";

import { withAlpha } from "@/lib/appearance";
import type { Palette } from "@/types";

/**
 * Clickable "you might also ask" questions under the latest answer.
 *
 * Generated by the backend with each answer. Clicking one sends it exactly as
 * if the visitor had typed it. Rendered as plain text, like every other piece
 * of model output (see MessageBubble).
 *
 * `palette` is the customer's colours on the public chatbot; without it the
 * chips wear the SKANDA AI theme, as in the dashboard playground.
 */
export function FollowUpQuestions({
  questions,
  onSelect,
  palette = null,
  disabled = false,
}: {
  questions: string[];
  onSelect: (question: string) => void;
  palette?: Palette | null;
  disabled?: boolean;
}) {
  if (questions.length === 0) return null;

  return (
    <div className="chat-turn flex flex-col items-start gap-1.5 pl-9" aria-label="Suggested questions">
      {questions.map((question) => (
        <button
          key={question}
          type="button"
          disabled={disabled}
          onClick={() => onSelect(question)}
          className="inline-flex max-w-full items-center gap-1.5 border border-burgundy-600/25 bg-surface px-3 py-1.5 text-left text-[13px] font-medium text-burgundy-700 transition-colors hover:bg-burgundy-50 disabled:opacity-50"
          style={
            palette
              ? {
                  borderColor: withAlpha(palette.primary, 0.35),
                  backgroundColor: palette.ai_bubble,
                  color: palette.primary,
                  borderRadius: "var(--chat-radius, 10px)",
                }
              : { borderRadius: "10px" }
          }
        >
          <CornerDownRight aria-hidden className="size-3.5 shrink-0 opacity-70" />
          <span className="min-w-0 break-words">{question}</span>
        </button>
      ))}
    </div>
  );
}
